const arcPoints = a => Array.from({ length: 65 }, (_, i) => pointAt(a * i / 64));

const title = new Text({ text: 'What is a radian?', color: WHITE, fontSize: 38 });
title.moveTo([0, 3.25, 0]);
const circle = new Circle({ radius: r, color: BLUE });
circle.moveTo(center);
const radius1 = new Polygon({ vertices: [center, pointAt(0)], color: GREEN });
radius1.setStrokeWidth(4).setFillOpacity(0);
