radius2.setStrokeWidth(4).setFillOpacity(0);
const arc = new Polygon({ vertices: arcPoints(theta), color: YELLOW });
arc.setStrokeWidth(7).setFillOpacity(0);
const centerDot = new Dot({ point: center, color: WHITE });
const endDot = new Dot({ point: pointAt(theta), color: YELLOW });

const formula = new Text({ text: 'angle = arc length / radius', color: WHITE, fontSize: 26 });
formula.moveTo([3.5, 1.4, 0]);
const oneRadian = new Text({ text: '1 radian: arc length = radius', color: YELLOW, fontSize: 24 });
